create table ruta_puntos (
    id uuid primary key default gen_random_uuid(),
    ruta_id uuid not null
        references rutas(id)
        on delete cascade,
    orden integer not null,
    latitud double precision not null,
    longitud double precision not null,
    unique (ruta_id, orden)
);

alter table vehiculos
    add column if not exists velocidad_maxima integer default 80,
    add column if not exists hora_salida text default '06:00';

alter table ruta_puntos enable row level security;
create policy lectura_ruta_puntos on ruta_puntos for select using (true);

update vehiculos set velocidad_maxima = 80, hora_salida = '06:00'
    where id = '00000000-0000-4000-8000-000000000301';
update vehiculos set velocidad_maxima = 80, hora_salida = '08:30'
    where id = '00000000-0000-4000-8000-000000000302';
update vehiculos set velocidad_maxima = 80, hora_salida = '05:00'
    where id = '00000000-0000-4000-8000-000000000303';
update vehiculos set velocidad_maxima = 90, hora_salida = '07:00'
    where id = '00000000-0000-4000-8000-000000000304';

update configuracion set version = 2, actualizado_en = now() where id = 1;
